def transform(grid):
    out = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    marker = next(v for row in grid for v in row if v != grid[0][0])
    for r in range(rows):
        pts = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(pts, pts[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(cols):
        pts = [r for r in range(rows) if grid[r][c] == marker]
        for a, b in zip(pts, pts[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
